 readonly Dictionary<string,string[]> quickLoaderVersions=new();bool quickCatalogLoading;string quickCatalogLoader="",quickCatalogError="";int quickCatalogGeneration;
 async Task PrepareQuickLoaderAsync(string loader){if(loader is not("Forge" or "Fabric"))return;int generation=++quickCatalogGeneration;quickCatalogLoader=loader;quickCatalogLoading=true;quickCatalogError="";SyncBrawlState();try{await LoadCatalogAsync();using var service=new QuickLoader();var supported=await service.SupportedMinecraftAsync(loader,catalogCts.Token);var available=remoteVersions.Where(v=>v.Type=="release"&&supported.Contains(v.Id,StringComparer.Ordinal)).Select(v=>v.Id).ToArray();if(generation!=quickCatalogGeneration)return;if(available.Length==0)throw new IOException(Loc.Language=="ru"?"Нет поддерживаемых версий. Повтори запрос.":"No supported versions found. Retry the request.");quickLoaderVersions[loader]=available;}catch(OperationCanceledException){}catch(Exception e){if(generation==quickCatalogGeneration)quickCatalogError=e.Message;}finally{if(generation==quickCatalogGeneration){quickCatalogLoading=false;SyncBrawlState();}}}
 bool quickLoaderIndeterminate;CancellationTokenSource? quickLoaderCts;string quickLoaderStatus="";
 async void QuickLoader_Click(object sender,RoutedEventArgs e){VersionPopup.IsOpen=false;string loader=((Button)sender).Tag?.ToString()??"Fabric";await PrepareQuickLoaderAsync(loader);if(quickCatalogError.Length>0){Status(quickCatalogError,true);return;}if(!quickLoaderVersions.TryGetValue(loader,out var supported)||supported.Length==0)return;var dialog=new Window{Title=Loc.Language=="ru"?"Установить "+loader:"Install "+loader,Width=420,Height=245,ResizeMode=ResizeMode.NoResize,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(34,36,44)),Foreground=System.Windows.Media.Brushes.White};var panel=new StackPanel{Margin=new Thickness(24)};panel.Children.Add(new TextBlock{Text="Minecraft · "+loader,FontSize=20,Margin=new Thickness(0,0,0,15)});var versionsBox=new ComboBox{ItemsSource=supported,SelectedItem=SelectedChoice?.BaseVersion,IsEditable=false};if(versionsBox.SelectedIndex<0)versionsBox.SelectedItem=supported.Contains("1.21.1")?"1.21.1":supported[0];panel.Children.Add(versionsBox);var install=new Button{Content=Loc.Language=="ru"?"Установить":"Install",Margin=new Thickness(0,18,0,0)};install.Click+=(s,args)=>{if(versionsBox.SelectedItem!=null){dialog.Tag=versionsBox.SelectedItem.ToString();dialog.DialogResult=true;}};panel.Children.Add(install);dialog.Content=panel;if(dialog.ShowDialog()==true&&dialog.Tag is string minecraft)await QuickInstallLoaderAsync(loader,minecraft);}
 async Task QuickInstallLoaderAsync(string loader,string minecraft){if(loader is not("Forge" or "Fabric")||quickLoaderCts!=null)return;if(installing||modBusy||launching||exportCts!=null||game is {HasExited:false}){Status(Loc.Language=="ru"?"Дождись завершения текущей операции и закрой игру.":"Finish the current operation and close the game.",true);return;}
 using var cts=new CancellationTokenSource();quickLoaderCts=cts;installing=true;PlayButton.IsEnabled=false;VersionCombo.IsEnabled=false;DownloadPanel.Visibility=Visibility.Visible;quickLoaderStatus=Loc.Language=="ru"?"Подготовка "+loader:"Preparing "+loader;Status(quickLoaderStatus);SyncBrawlState();
 try{using var service=new QuickLoader();var vanillaProgress=new Progress<InstallProgress>(p=>{quickLoaderIndeterminate=p.Total<=0;DownloadBar.IsIndeterminate=quickLoaderIndeterminate;ShowDownloadProgress(p);quickLoaderStatus=p.Stage;SyncBrawlState();});var loaderProgress=new Progress<ModProgress>(p=>{quickLoaderIndeterminate=true;DownloadBar.IsIndeterminate=true;quickLoaderStatus=p.Stage;DownloadTitle.Text=p.Stage;Status(p.Stage);SyncBrawlState();});string id=await Task.Run(()=>service.InstallAsync(settings.GameRoot,minecraft,loader,vanillaProgress,loaderProgress,cts.Token));await RefreshVersions();selectedChoice=choices.FirstOrDefault(v=>v.Id==id);UpdateChoices(id);settings.Version=id;if(!suppressProfileSave)settings.Save();quickLoaderStatus=loader+" · "+minecraft+(Loc.Language=="ru"?" установлен":" installed");Status(quickLoaderStatus);}
 catch(OperationCanceledException){quickLoaderStatus=Loc.Language=="ru"?"Установка отменена.":"Installation cancelled.";Status(quickLoaderStatus);}catch(Exception ex){quickLoaderStatus=ex.Message;Status(quickLoaderStatus,true);Log("Loader: "+ex.Message);}finally{quickLoaderCts=null;quickLoaderIndeterminate=false;DownloadBar.IsIndeterminate=false;installing=false;VersionCombo.IsEnabled=true;DownloadPanel.Visibility=Visibility.Collapsed;UpdateLaunchButton();SyncBrawlState();}
